window.BIZ_PAPERS = (window.BIZ_PAPERS || []).concat([{"id": "MEDI2-SAM", "unit": 2, "key": "SAM", "series": "Sample assessment (AAQ)", "date": "Pearson sample assessment material", "title": "Pearson sample paper", "source": "pearson", "kind": "exam", "code": "Sample", "spec": "new", "total": 80, "minutes": 120, "items": [{"q": 1, "sub": "a", "marks": 1, "section": "A", "ctx": ["Diagnostic techniques Amniocentesis is a test used to screen a foetus for genetic disorders."], "text": "Name one genetic condition that the test results from amniocentesis can\ndiagnose.", "ms": {"body": "Award one mark for a correctly given genetic condition that can\nbe diagnosed from amniocentesis:\n• Down syndrome\n• Cystic fibrosis\nAccept any other appropriate response", "levels": null}}, {"q": 1, "sub": "b", "marks": 1, "section": "A", "ctx": [], "text": "Identify when amniocentesis is usually performed.\nA  Between 10 and 15 weeks of pregnancy\nB  Between 15 and 20 weeks of pregnancy\nC  Between 25 and 30 weeks of pregnancy\nD  Between 30 and 40 weeks of pregnancy", "ms": {"body": "Award one mark for the correct response\n• B - Between 15 and 20 weeks of pregnancy", "levels": null}}, {"q": 1, "sub": "c", "marks": 2, "section": "A", "ctx": [], "text": "Give two reasons why amniocentesis would be offered as a diagnostic test.", "ms": {"body": "Award one mark for each correctly given reasons why\namniocentesis would be offered as a diagnostic test, up to a\nmaximum of two marks, from:\n• family history if genetic disease (1)\n• advanced maternal age (1)\n• ultrasound showed abnormal results (1)\nAlso, accept named examples of:\n• family history of genetic disease\n• advanced maternal age\n• ultrasound showed abnormal results", "levels": null}}, {"q": 1, "sub": "d", "marks": 1, "section": "A", "ctx": [], "text": "Name one test other than amniocentesis that can be performed on a foetus to\nscreen for genetic disorders.", "ms": {"body": "Award one mark for a correctly given test that can be performed\non a foetus to screen for genetic disorders:\n• chorionic villus sampling/CVS\nAccept any other appropriate response", "levels": null}}, {"q": 1, "sub": "e", "marks": 3, "section": "A", "ctx": [], "text": "Describe the process of amniocentesis.", "ms": {"body": "Award one mark for each of the following points given in the\ncorrect order, up to a maximum of three marks.\nInsert a needle into the [uterus/amniotic sac] using\nultrasound (1), take a sample of amniotic fluid (1), test the\n[foetal cells/DNA] contained in the amniotic fluid b(1)\nDo not accept:\n-\nInsert needle into [uterus/amniotic sac] unless qualified\nhow the needle is inserted safely\n-\nTake a sample without qualifying what the sample taken\nis.\n-\nTest the sample without qualifying what is being tested", "levels": null}}, {"q": 2, "sub": "a", "marks": 1, "section": "A", "ctx": ["Immune response"], "text": "Name one type of white blood cell that allows rapid production of antibodies in a\nsecondary immune response.", "ms": {"body": "Award one mark for a correctly named type of white blood cell\nthat allows rapid production of antibodies in a secondary immune\nresponse from:\n• memory cell\n• B-memory cell\n• T-memory cell\n• plasma cell\n• effector cell", "levels": null}}, {"q": 2, "sub": "b", "marks": 1, "section": "A", "ctx": [], "text": "Name the part of the antibody that is specific to a pathogen antigen and enables\nphagocytosis.", "ms": {"body": "Award one mark for the correct part of the antibody that is\nspecific to a pathogen antigen which enables phagocytosis from:\n• antigen binding site (1)\n• variable region (1)", "levels": null}}, {"q": 2, "sub": "c", "marks": 4, "section": "A", "ctx": [], "text": "Figure A1 shows the concentration of an antibody in a person’s blood after the\nfirst and second exposure to a pathogen.\nConcentration\nof antibody\nTime\nprimary\nimmune\nresponse\nsecond exposure\nsecondary\nimmune\nresponse\nﬁrst exposure\nFigure A1\nCalculate the percentage increase in the concentration of an antibody between\nthe primary and secondary immune response shown in Figure A1.", "ms": {"body": "Award four marks for the correct answer of:\n• 175\nIf the answer is incorrect:\n• award one mark for recall of the formula in words or\nnumbers\n  - ((Secondary immune response – primary immune\nresponse) / primary immune response) x 100\n  - ((5.5 – 2) / 2) x 100\n• award one mark for identifying the correct value for the\nprimary immune response\n  - 5.5\n• award one mark for identifying the correct value for the\nsecondary immune response\n  - 2\n• award one mark for calculating value of percentage change\nusing own figures for Secondary and Primary immune\nresponse (ECF)", "levels": null}}, {"q": 2, "sub": "d", "marks": 3, "section": "A", "ctx": ["Show your working Percentage increase = %"], "text": "Explain the difference between the speed of the primary immune response and\nthe speed of the secondary immune response, shown in Figure A1.", "ms": {"body": "Award one mark for a correct difference between the speed of\nthe primary immune response and the speed of the secondary\nimmune response (1), one mark for a justification for that\ndifference (1), and one mark for an expansion of the\njustification (1), up to a maximum of three marks\n• secondary response is faster (1) because there are\n{memory cells/B lymphocytes} in body produced during\nprimary immune response (1) which causes the immune\nsystem to {respond/produce antibodies} sooner (1)\n• primary response is slower (1) because a single B or T\ncell that recognises an antigen that enters the body is\nselected from the pre-existing cell pool of differing\nantigen specificities (1) and then reproduces to generate\na clonal cell population that eliminates the antigen (1).\nAccept any other appropriate response\nMarking points may be given in any order", "levels": null}}, {"q": 3, "sub": "a", "marks": 1, "section": "A", "ctx": ["Gene Expression"], "text": "Figure A2 shows a mutation in a DNA sequence.\nOriginal DNA sequence CCT GAG GAG AAG\nMutated DNA sequence CCT GTG GAG AAG\nFigure A2\nName the type of mutation shown in Figure A2.", "ms": {"body": "Award one mark for the correct name of the mutation shown in\nFigure A2 from:\n• substitution (mutation) (1)\n• point (mutation) (1)\nAlso accept:\n• missense", "levels": null}}, {"q": 3, "sub": "b(i)", "marks": 1, "section": "A", "ctx": [], "text": "State what is meant by the term acquired mutation.", "ms": {"body": "Award one mark for a correct definition of the term acquired\nmutation:\n• a change in single (somatic) cell which {occur after\nconception/later in life/are spontaneous} (1)\nAccept any other appropriate/alternative responses", "levels": null}}, {"q": 3, "sub": "b(ii)", "marks": 1, "section": "A", "ctx": [], "text": "Give one cause of an acquired mutation.", "ms": {"body": "Award one mark for a correctly given way that mutations can be\nacquired from:\n• exposure to radiation\n• exposure to chemicals\n• errors in cell cycle\n• errors during mitosis\nAlso, accept named examples of causes\nAccept any other appropriate/alternative responses", "levels": null}}, {"q": 3, "sub": "c", "marks": 4, "section": "A", "ctx": [], "text": "One location within DNA where a mutation can happen is in a non-coding\nsequence.\nThis type of mutation can affect the binding of RNA polymerase and change the\nrate of expression of the gene.\nComplete the table to:\n• state two locations where mutations can occur\n• give one effect a mutation at each of the locations has on the expression of a\ngene.", "ms": {"body": "Award one mark for each of the following points given in the correct order, up to a maximum of 4 marks.\nLocations where mutations can occur\nEffect of the mutation\nin start codon (1)\nthe protein does not get made (1)\nin a stop codon (1)\naltering /increasing the length of the protein chain (1)\nmay change a control gene (1)\naltering which genes are switched on or off in a cell/ change to\nthe cell cycle/cell division (1)\nmay turn on (proto)oncogene/ turn off\na tumour suppressor gene (1)\nincreasing cell division (1)", "levels": null}}, {"q": 4, "sub": "a(i)", "marks": 1, "section": "A", "ctx": ["Diagnostic techniques A doctor measures the core body temperature of the patient. The patient’s core body temperature is recorded as 39.3 °C"], "text": "Give one possible diagnosis for the patient for a core body temperature of\n39.3 °C", "ms": {"body": "Award one mark for the following:\n• an infection\n• medical condition\nAccept any other appropriate/alternative responses.\nAlso accept named examples", "levels": null}}, {"q": 4, "sub": "a(ii)", "marks": 2, "section": "A", "ctx": [], "text": "Explain one effect a core body temperature of 39.3 could have on a patient’s\nbody.", "ms": {"body": "Award one mark for a correct one effect a core body temperature of\n39.3 could have on a patient’s body (1) and one mark for a\njustification for that effect (1), up to a maximum of two marks\n• metabolic reactions would be affected (1) because the high\ntemperature would cause enzymes to start to denature (1)\nMarking points may be reversed/given in any order\nAccept any other appropriate/alternative responses", "levels": null}}, {"q": 4, "sub": "b", "marks": 3, "section": "A", "ctx": [], "text": "The doctor also uses a nerve conduction velocity (NCV) test to diagnose the\npatient.\nThe doctor takes multiple readings so that a mean average can be given.\nFigure A3 snips the 5 readings of the speed recorded in the nerve conduction\nvelocity test.\nReading\nNCV m/s\n24.7\n28.4\n62.0\n26.5\n24.4\nFigure A3\nCalculate, using Figure A3, the mean average of the nerve conduction velocity\nreadings for the patient.", "ms": {"body": "Award three marks for the correct answer\n• 26\nIf the answer is incorrect:\n• Award two marks for the formula for calculating mean in\nwords or numbers in which the student has recognised\nthe need to remove the anomalous reading:\n  - Mean = Total of valid readings / number of valid\nreadings\n  - Mean = (24.7 + 28.4 + 26.5 + 24.4) / 4\nOR\n• Award one mark for the formula for calculating mean in\nwords or numbers in which the student has failed to\nrecognise the need to remove the anomalous reading\n  - Mean = (24.7 + 28.4 + 62.0 + 26.5 + 24.4) / 5\nAND\n• Award one mark for calculating mean value of readings\nusing own figures for the total value of the readings\nand/or total number of readings (ECF)\nOR\n• Award one mark for working demonstrating the student\nhas recognised the need to remove the anomalous\nreading but which show they did not know how to\ncalculate mean\n  - Mean = (24.7 + 28.4 + 26.5 + 24.4) / 5\nAND\n• Award one mark for calculating mean value of readings\nusing own figures for the total value of the readings\nand/or total number of readings (ECF)", "levels": null}}, {"q": 4, "sub": "c", "marks": 3, "section": "A", "ctx": ["Show your working Nerve conduction velocity = m/s"], "text": "Explain one reason why a person with Multiple Sclerosis (MS) could have NCV\nreadings and EMG readings below the normal range.", "ms": {"body": "Award one mark for a correct reason why a person with Multiple\nSclerosis (MS) could have NCV readings and EMG readings below\nthe normal range (1), one mark for a justification for that reason\n(1), and a one mark for an expansion of the justification (1) up\nto a maximum of three marks\n• MS attacks/degrades Schwann cells (in the CNS) (1)\nbecause there is decreased myelin on the patient’s\nneurons (1) which reduces saltatory conduction (1)\nMarking points may be reversed/given in any order", "levels": null}}, {"q": 5, "sub": "a", "marks": 1, "section": "A", "ctx": ["Genetic conditions"], "text": "State the function of a gene.", "ms": {"body": "Award one mark for a correctly stated function of a gene:\n• (a gene) provides the amino acid sequence for a specific\nprotein", "levels": null}}, {"q": 5, "sub": "b", "marks": 2, "section": "A", "ctx": [], "text": "People with cystic fibrosis produce a thick sticky mucus in their pancreas and\nsmall intestine, and need a diet that has a higher energy content than people\nwho do not have cystic fibrosis.\nExplain one reason why the production of thick sticky mucus means people with\ncystic fibrosis need a high energy diet.", "ms": {"body": "Award one mark for a correct reason why people with cystic fibrosis\nneed a diet that has a higher energy content than people who do\nnot have cystic fibrosis (1) and one mark for a justification for that\nreason (1), up to a maximum of two marks.\n• The digestive system of people with cystic fibrosis is less\nefficient at extracting {energy/amino acids/ glucose} from\nfood (1) because the mucus blocks the release of digestive\nenzymes (into the small intestine) (1)\n• The digestive system of people with cystic fibrosis absorbs\nfewer molecules (of amino acids/ glucose) into the blood (1)\nbecause the mucus increases the diffusion pathway of\nnutrients to the intestinal lining (1)\nAccept any other appropriate/alternative responses\nMarking points may be reversed/given in any order", "levels": null}}, {"q": 5, "sub": "c", "marks": 3, "section": "A", "ctx": ["Figure A4 shows two parents within a family pedigree for cystic fibrosis. Parents Offspring Key Male carrier of cystic fibrosis Female carrier of cystic fibrosis Figure A4"], "text": "The two parents in Figure A4 have 6 children.\nThree of the children would be expected to be carriers of cystic fibrosis.\nShow that 3 of the children from the parents in Figure A4 would be expected to\nbe carriers of cystic fibrosis.", "ms": {"body": "Award one mark for any of the following, up to a maximum of\nthree marks\n• A correctly drawn punnet square diagram that:\n  - demonstrates the student has recognised that both\nparents are heterozygous/ Dd (1)\n  - correctly shows the potential combination of alleles\nmother\nD d\nfather\nD DD Dd d Dd dd\nA conclusion that demonstrates the student has correctly\ninterpreted the diagram to determine that 50% of the children (i.e.\n3 children) would be carriers (1)", "levels": null}}, {"q": 5, "sub": "d", "marks": 2, "section": "A", "ctx": ["Show your working using a Punnet square Probability of children being carriers of cystic fibrosis"], "text": "Explain one ethical concern with conducting whole genome sequencing in\nnewborns.", "ms": {"body": "Award one mark for a correct ethical concern with conducting\nwhole genome sequencing in newborns (1) and one mark for a\njustification for that reason (1), up to a maximum of two marks\n• Conducting whole genome sequencing in newborns could\ncause {anxiety from unnecessary treatments / concern if\nthe condition is not treatable} (1) because there is a risk\nof {misdiagnosis / false positives} (1)\n• Conducting whole genome sequencing in newborns could\nraise questions about how and when the results would be\nshared with the children (1) because the law is unclear\nabout when such information must be shared with\nsomeone who was unable to provide consent (1)\n• Conducting whole genome sequencing in newborns could\nraise questions of fairness in the use of genetic information\n(1) because the risk of genetic discrimination grows as\nnew disease susceptibility genes are identified (1)\nAccept any other appropriate/alternative responses", "levels": null}}, {"q": 6, "sub": "a", "marks": 1, "section": "A", "ctx": ["Immune Dysfunction"], "text": "Name one test that can be used to diagnose an autoimmune disease in a patient.", "ms": {"body": "Award one mark for a correctly given test used to diagnose an\nautoimmune disease in a patient from:\n• C-reactive protein (CRP) blood test\n• Antinuclear antibody (ANA) test\n• Complete blood count (CBC) with white blood cell differential\nAccept any other appropriate/alternative responses", "levels": null}}, {"q": 6, "sub": "b", "marks": 2, "section": "A", "ctx": [], "text": "Explain one reason why Crohn’s disease is classified as an autoimmune disease.", "ms": {"body": "Award one mark for a correct reason why Crohn’s disease is classified\nas an autoimmune disease (1) and one mark for a justification for that\nreason (1), up to a maximum of two marks\n• The symptoms of Crohn’s disease are caused by inflammation in\nthe digestive tract (1) because the immune system mistakenly\nattacks healthy cells in the body (1)\nMarking points may be reversed/given in any order", "levels": null}}, {"q": 6, "sub": "c(i)", "marks": 3, "section": "A", "ctx": ["Another autoimmune disease is human immunodeficiency virus (HIV).", "Figure A5 shows the expected ranges for platelets and white blood cells in a", "whole blood count of a non-HIV patient.", "Blood cell or substance", "Range in a normal whole blood count", "Platelets", "150–400 × 109/l", "White blood cells", "4.0–11 × 109/l", "– Neutrophils", "2.0–7.5 × 109/l", "– Lymphocytes", "1.5–4.5 × 109/l", "Figure A5"], "text": "Explain one potential difference in a normal whole blood count compared to\nthe expected whole blood count for a patient with human immunodeficiency\nvirus (HIV).", "ms": {"body": "Award one mark for a potential difference in a normal blood count\ncompared to the expected whole blood count for a patient for human\nimmunodeficiency virus (HIV) (1), one mark for a justification for that\nreason (1), and a one mark for an expansion of the justification (1) up\nto a maximum of three marks\n• Lymphocytes are likely to be lower (1) because HIV attacks the\nCD-4 cells (1) because of injection of the viral genome into the\nhost cell (1)", "levels": null}}, {"q": 6, "sub": "c(ii)", "marks": 3, "section": "A", "ctx": [], "text": "Explain one potential similarity in a normal whole blood count to the\nexpected whole blood count for a patient with human immunodeficiency\nvirus (HIV).", "ms": {"body": "Award one mark for a correct similarity in a normal whole blood count\nto the expected whole blood count for a patient with human\nimmunodeficiency virus (HIV) (1), one mark for a justification for that\nsimilarity (1), and a one mark for an expansion of the similarity (1) up\nto a maximum of three marks\n• Total white blood cell count is likely to be within the normal\nrange (1) because there are a number of different white blood\ncells and some will increase but some will decrease (1) because\nHIV is a progressive disease and would depend on the stage of\ninfection (1)", "levels": null}}, {"q": 7, "sub": "a", "marks": 1, "section": "B", "ctx": ["Cancer Breast cancer is a malignant tumour in or around breast tissue."], "text": "Give one other type of tumour.", "ms": {"body": "Award one mark for a correct type of tumour:\n• benign (1)", "levels": null}}, {"q": 7, "sub": "b", "marks": 2, "section": "B", "ctx": [], "text": "Explain one reason why tumour cells can grow where somatic cells cannot.", "ms": {"body": "Award one mark for a correct reason why tumour cells can grow\nwhere somatic cells cannot (1) and one mark for a justification\nfor that reason (1), up to a maximum of two marks\n• Tumour cells are able to survive and grow {under hypoxic\nconditions / when oxygen demand exceeds oxygen supply}\n(1) because tumour cells need less oxygen to carry out\ncellular activities (1)", "levels": null}}, {"q": 7, "sub": "c", "marks": 3, "section": "B", "ctx": [], "text": "Explain one reason why early detection of a malignant tumour increases the\nchance of patient’s survival.", "ms": {"body": "Award one mark for a correct reason why early detection of a\nmalignant tumour increases the chance of survival (1), one mark\nfor an explanation of that reason (1), and a one mark for an\nexpansion of the explanation (1) up to a maximum of three\n• The tumour is more likely to be more responsive to range\nof treatment options (1) because the tumour is likely to be\nsmaller/{less differentiated / have fewer mutations}/ less\nlikely to have metastasized (1) and therefore leading to an\nimproved quality and longevity of life after treatment (1)", "levels": null}}, {"q": 8, "sub": "a(i)", "marks": 1, "section": "B", "ctx": ["Interpretation, analysis and evaluation of scientific information Questions 8, 9, 10 and 11 are based on the extract of the article in a separate booklet. Quantitative and qualitative evidence The data collection method used in Figure B3 was a retrospective cohort study."], "text": "State the meaning of the term retrospective cohort study.", "ms": {"body": "Award one mark for a correct meaning of the term retrospective\nstudy:\n• the analysis of data that was originally collected for\nreasons other than research (1)", "levels": null}}, {"q": 8, "sub": "a(ii)", "marks": 2, "section": "B", "ctx": [], "text": "Another data collection method is collecting primary data through\nquestionnaires.\nExplain one drawback of using questionnaires as a data collection method.", "ms": {"body": "Award one mark for a correct drawback of using questionnaires\nas a data collection method (1) and one mark for an explanation\nfor that drawback (1), up to a maximum of two marks\n• questionnaires can be an incomplete/ inaccurate data\ncollection method (1) because the researcher has less\ncontrol over the results (1)\n• conducting data collection through questionnaires can be\ntime-consuming (1) because this would involve that\ninvolves collation of the results before analysis (1)\n• questionnaires can decrease the reliability of conclusions\n(1) because there are a number of factors that could effect\nthe responses, for example the phrasing of the question,\nthe likelihood to give accurate responses, etc.", "levels": null}}, {"q": 8, "sub": "b", "marks": 3, "section": "B", "ctx": [], "text": "Explain one trend in the data shown in Figure B3.", "ms": {"body": "Award one mark for a correct trend in figure B1 (1) one mark for\na justification for that trend (1), and one mark for an expansion of\nthe justification (1), up to a maximum of three marks.\n• The trend in Figure B3 shows that the percentage of\nwomen with at least one false positive increased with the\nnumber of mammograms for the 2400 in the study (1).\nThis could be because all medical screening tests have a\nchance of a false positive (1). Therefore, there is an\nincreased probability that the more a woman is screened\nwith the same test there is a chance that at least one of\nthe tests will be a false positive (1)\n• One trend is that as the number of mammograms\nincreases the confidence interval widens (1) This could be\nbecause the sample size is relatively small (1) which\ndecreases the precise of the data (1)", "levels": null}}, {"q": 9, "sub": "", "marks": 3, "section": "B", "ctx": [], "text": "Conducting data analysis\nExplain one possible extrapolation of the mortality rate of women aged 50–69 from\nthe data in Figure B1.", "ms": {"body": "Award one mark for a possible extrapolation (1) one mark for an\nexplanation for that extrapolation (1), and one mark for an\nexpansion of the explanation (1), up to a maximum of three\nThe mortality rate of women aged 50-69 is likely to continue to\ndecrease (1), because of advancements in science/ treatments (1)\nbut some people will always die from cancer until there is a\ncomplete cure (1)", "levels": null}}, {"q": 10, "sub": "", "marks": 6, "section": "B", "ctx": [], "text": "Discuss how the NHS influences public opinion on cancer screening.", "ms": {"body": "Answers will be credited according to the learner’s demonstration\nof knowledge and understanding of the material, using the\nindicative content and levels descriptors below. The indicative\ncontent that follows is not prescriptive. Answers may cover some\nor all of the indicative content, but learners should be rewarded\nfor other relevant answers\n• The NHS is a publicly-funded healthcare system\n• The NHS introduced the breast screening programme in\n1988 and by 1994 this covered the whole of the UK.\n• The NHS diagnoses and treats cancer based on screening\nprogramme outcomes\n• The level of screening may be made on the basis of the\nfinancial resources available or priorities set in the NHS\n• The NHS has budget and targets\n• They mainly support cancer screening through a cost-\nbenefit analysis and how reliable the tests are\n• The data in B1 supports that the breast screening\nprogramme from the NHS has decreased the mortality rate\nper 1000,000 people consistently for the 50-69 years old\nage bracket as women are invited for breast screening\nappointments every 4 years from their 50th birthday until\ntheir 71st birthday.\n• The mortality rate from breast cancer for over 70-year-olds\nand under 50-year-olds does not show the same trend.\n• However, there is negative press surrounding the breast\nscreening programme, to the extent that B2 shows NHS\nbreast screening appointments are missed by more than\n25% of those invited.\n10 51\nLevel\nDescriptor - Discuss 6 marks\nRefer to Levels-Based Mark Scheme Guidance\nGuidance to markers:\nAll traits carry equal weighting.\n0 0\nNo rewardable material\n1\n1-2\n• Demonstrates a basic analysis of the situation by\nsuperficially breaking down the different aspects into their\ncomponent parts\n• Demonstrates basic application of knowledge and\nunderstanding that is partially relevant to the context of the\n2\n3-4\n• Demonstrates a good analysis of the situation by breaking\ndown the different aspects into their component parts\n• Demonstrates good application of knowledge and\nunderstanding that is relevant to the context of the question\n3\n5-6\n• Demonstrates a thorough analysis of the situation by\ncomprehensively breaking down the different aspects into\ntheir component parts\n• Demonstrates comprehensive application of knowledge and\nunderstanding that is consistently relevant to the context of\nthe question\n52 11\nAnswers will be credited according to the learner’s demonstration of\nknowledge and understanding of the material, using the indicative content\nand levels descriptors below. The indicative content that follows is not\nprescriptive. Answers may cover some or all of the indicative content, but\nlearners should be rewarded for other relevant answers\nThe conclusion could be considered to be valid because:\n• data in Figure B2 suggests there is a reluctance to attend cancer\nscreening appointments\n• the article attributes this to the risk and subsequent anxiety that\ncould be caused, of false positives.\nHowever, the data may not be valid or reliable:\n• There is no qualitative data has been presented in the article\n• There are no peer-reviewed qualitative research of women’s personal\nexperiences of receiving a false-positive screening test result for\nbreast cancer\nThere could be a range of sources of error in data, including systematic,\nrandom, procedural, sample selection.\nFigure B1\n• likely to be primary data from NHS database, and so unlikely to be\nbias/ should be factual and there is a large sample size.\n• data is also likely to be verified or peer reviewed.\n• However, this only shows data between 1974 and 2004 (mortality\nrates since 2004 could have changed with advancing technology and\nso not show an accurate representation of the issue).\n• The use of the age groups could highlight the risk after 50, which is\nwhen women are invited to have cancer screening.\nFigure B2\n• likely to be secondary data\n• covering from 2008 to 2018.\n• Unclear what the level of uptake of cancer screening appointments\nhave been since.\n• Covid could have caused a decreased in uptake.\n• Author would have been a daily mail journalist, expertise unknown\n• Data could have been selected for sensationalism\n• There is a large sample size.\n• The data is unlikely to be peer reviewed.\n• However, the use of acceptable and achievable levels have not been\ndefined but have been used to highlight a problem and\nsensationalise the issue for sales of tabloid newspapers\n53\nFigure B3\n• secondary data and it is unknown how the data was collected\n• J. G. Elemore - could have selected particular women, or only\nwomen with false positives responded\n• small sample size but is a retrospective cohort and so may be its\nmaximum size\n• sample selection could have been limited or dictated.\n• It is unclear how the data from collected- could have been NHS data\nor questionnaire, but lifestyle factors may not have been consistent\nbetween the women and so data could contain errors\n• there are no women with 10 mammograms, but data has been\nextrapolated to give this value on the graph.\n• From 1998 and false positives could have changed since 1998 with\nadvances in technology.\n• J.G Elemore et al likely to have expertise, but source of funding is\nunknown and so could be neutral or could be biased.\n• Published in The New England Journal of Medicine and so likely to be\npeer reviewed.\nLevel   Mark\nDescriptor - Discuss 9 marks\nRefer to Levels-Based Mark Scheme Guidance\nGuidance to markers:\nThe second trait (application) carries twice as much weighting as the first trait (analysis).\n0 0\nNo rewardable material\n1\n1 - 3\n• Demonstrates a basic analysis of the situation by superficially\nbreaking down the different aspects into their component parts\n• Demonstrates basic application of knowledge and understanding\nthat is partially relevant to the context of the question\n2\n4 - 6\n• Demonstrates a good analysis of the situation by breaking down\nthe different aspects into their component parts\n• Demonstrates good application of knowledge and understanding\nthat is relevant to the context of the question\n7 - 9\n• Demonstrates a thorough analysis of the situation by\ncomprehensively breaking down the different aspects into their\ncomponent parts\n• Demonstrates comprehensive application of knowledge and\nunderstanding that is consistently relevant to the context of the\n54\nApril 2026\nFor information about Pearson Qualifications, including Pearson Edexcel\nand BTEC qualifications visit qualifications.pearson.com\nEdexcel and BTEC are registered trademarks of Pearson Education Limited\nPearson Education Limited. Registered in England and Wales No. 872828\nRegistered Office: 80 Strand, London WC2R 0RL.\nVAT Reg No GB 278 537121", "levels": null}}, {"q": 11, "sub": "", "marks": 9, "section": "B", "ctx": [], "text": "An evaluation of the evidence shown in the resource booklet concluded:\n“More should be done to minimise the fear of cancer screening.”\nDiscuss the validity of the conclusion that “more should be done to minimise the fear\nof cancer screening.”", "ms": {"body": "Mark against the command word and the marks available; see the levels descriptors for extended answers.", "levels": null}}], "badge": "Pearson · current spec", "badgeTone": "new", "notice": "Pearson’s sample assessment for the current AAQ specification: the closest match to the real exam. Figures, tables and information booklets are described in words."}]);
